"use client";

import { useEffect, useState } from "react";
import { VendorListingAddonsManager } from "@/components/vendors/VendorListingAddonsManager";

type Listing = { id: string; vendor_profile_id: string; name: string; category: string; subcategory: string | null; description: string; pricing_model: "fixed" | "starting_at" | "custom_quote"; starting_price: number | null; capacity: number | null; duration_minutes: number | null; booking_requirements: string | null; terms: string | null; status: string; moderation_note: string | null; submitted_at: string | null; reviewed_at: string | null; created_at: string; updated_at: string };
type ListingFields = { name: string; category: string; subcategory: string; description: string; pricingModel: Listing["pricing_model"]; startingPrice: string; capacity: string; durationMinutes: string; bookingRequirements: string; terms: string };
const initial: ListingFields = { name: "", category: "", subcategory: "", description: "", pricingModel: "fixed", startingPrice: "", capacity: "", durationMinutes: "", bookingRequirements: "", terms: "" };

export function VendorListingsManager({ filter = "all" }: { filter?: string }) {
  const [items, setItems] = useState<Listing[]>([]);
  const [fields, setFields] = useState<ListingFields>(initial);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [showForm, setShowForm] = useState(filter === "create-listing");
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [addonsOpenId, setAddonsOpenId] = useState<string | null>(null);
  const input = "w-full rounded-xl border border-[#EAD2B0] bg-[#FFFCF6] px-3 py-2.5 text-sm dark:border-[#4D3331] dark:bg-[#1A1211]";

  const refresh = async () => {
    setLoading(true); setError(null);
    try { const response = await fetch("/api/vendors/listings", { cache: "no-store" }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Listings could not be loaded."); setItems(data.listings ?? []); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Listings could not be loaded."); }
    finally { setLoading(false); }
  };
  useEffect(() => { void refresh(); }, []);
  useEffect(() => { setShowForm(filter === "create-listing"); }, [filter]);

  const edit = (item: Listing) => { setEditingId(item.id); setFields({ name: item.name, category: item.category, subcategory: item.subcategory || "", description: item.description, pricingModel: item.pricing_model, startingPrice: item.starting_price === null ? "" : String(item.starting_price / 100), capacity: item.capacity === null ? "" : String(item.capacity), durationMinutes: item.duration_minutes === null ? "" : String(item.duration_minutes), bookingRequirements: item.booking_requirements || "", terms: item.terms || "" }); setShowForm(true); };
  const save = async (submit = false) => {
    setBusy(true); setError(null); setNotice(null);
    const price = fields.startingPrice.trim() ? Math.round(Number(fields.startingPrice) * 100) : null;
    const payload = { ...(editingId ? { id: editingId } : {}), name: fields.name, category: fields.category, subcategory: fields.subcategory || null, description: fields.description, pricingModel: fields.pricingModel, startingPrice: fields.pricingModel === "custom_quote" ? null : price, capacity: fields.capacity ? Number(fields.capacity) : null, durationMinutes: fields.durationMinutes ? Number(fields.durationMinutes) : null, bookingRequirements: fields.bookingRequirements || null, terms: fields.terms || null, status: submit ? "pending_approval" : "draft" };
    try { const response = await fetch("/api/vendors/listings", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Listing could not be saved."); setNotice(submit ? "Listing submitted for administrator review." : "Draft saved."); setFields(initial); setEditingId(null); setShowForm(false); await refresh(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Listing could not be saved."); }
    finally { setBusy(false); }
  };
  const action = async (id: string, kind: "submit" | "delete") => {
    if (kind === "delete" && !window.confirm("Delete this draft listing?")) return;
    setBusy(true); setError(null); setNotice(null);
    try { const response = await fetch("/api/vendors/listings", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id, action: kind }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Listing could not be updated."); setNotice(kind === "submit" ? "Listing submitted for review." : "Draft deleted."); await refresh(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Listing could not be updated."); }
    finally { setBusy(false); }
  };

  const filtered = items.filter((item) => filter === "all" || filter === "create-listing" || filter === "packages" || (filter === "published" ? item.status === "published" : filter === "drafts" ? item.status === "draft" : filter === "pending-approval" ? item.status === "pending_approval" : filter === "rejected" ? item.status === "rejected" : true));
  return <section className="space-y-5 rounded-3xl border border-[#EAD2B0] bg-[#FFFCF6] p-5 shadow-sm dark:border-[#4D3331] dark:bg-[#241918]">
    <div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-serif text-2xl font-bold text-[#681B1D] dark:text-[#EAD2B0]">Service listings</h2><p className="mt-1 text-sm text-[#7D6B63]">Create a draft, then submit it for administrator review. Vendors cannot publish listings themselves.</p></div><button onClick={() => { setEditingId(null); setFields(initial); setShowForm((value) => !value); }} className="rounded-xl bg-[#681B1D] px-4 py-2.5 text-sm font-semibold text-white">{showForm ? "Close form" : "Create listing"}</button></div>
    {error && <p role="alert" className="rounded-xl bg-rose-50 p-3 text-sm text-rose-800">{error}</p>}{notice && <p role="status" className="rounded-xl bg-emerald-50 p-3 text-sm text-emerald-800">{notice}</p>}
    {showForm && <form onSubmit={(event) => { event.preventDefault(); void save(false); }} className="space-y-3 rounded-2xl border border-[#EAD2B0] bg-[#FFF3E3] p-4 dark:border-[#4D3331] dark:bg-[#1A1211]"><div className="grid gap-3 sm:grid-cols-2"><label className="text-xs font-semibold">Listing name<input required minLength={2} maxLength={160} className={`${input} mt-1`} value={fields.name} onChange={(event) => setFields({ ...fields, name: event.target.value })}/></label><label className="text-xs font-semibold">Category<input required maxLength={120} className={`${input} mt-1`} value={fields.category} onChange={(event) => setFields({ ...fields, category: event.target.value })}/></label><label className="text-xs font-semibold">Subcategory<input maxLength={120} className={`${input} mt-1`} value={fields.subcategory} onChange={(event) => setFields({ ...fields, subcategory: event.target.value })}/></label><label className="text-xs font-semibold">Pricing model<select className={`${input} mt-1`} value={fields.pricingModel} onChange={(event) => setFields({ ...fields, pricingModel: event.target.value as Listing["pricing_model"] })}><option value="fixed">Fixed price</option><option value="starting_at">Starting at</option><option value="custom_quote">Custom quotation</option></select></label>{fields.pricingModel !== "custom_quote" && <label className="text-xs font-semibold">Starting price (₹)<input type="number" min="0" step="0.01" required className={`${input} mt-1`} value={fields.startingPrice} onChange={(event) => setFields({ ...fields, startingPrice: event.target.value })}/></label>}<label className="text-xs font-semibold">Capacity (optional)<input type="number" min="1" max="100000" className={`${input} mt-1`} value={fields.capacity} onChange={(event) => setFields({ ...fields, capacity: event.target.value })}/></label><label className="text-xs font-semibold">Duration in minutes (optional)<input type="number" min="1" max="10080" className={`${input} mt-1`} value={fields.durationMinutes} onChange={(event) => setFields({ ...fields, durationMinutes: event.target.value })}/></label></div><label className="block text-xs font-semibold">Description<textarea maxLength={5000} className={`${input} mt-1`} rows={4} value={fields.description} onChange={(event) => setFields({ ...fields, description: event.target.value })}/></label><label className="block text-xs font-semibold">Booking requirements<textarea maxLength={3000} className={`${input} mt-1`} rows={2} value={fields.bookingRequirements} onChange={(event) => setFields({ ...fields, bookingRequirements: event.target.value })}/></label><label className="block text-xs font-semibold">Terms<textarea maxLength={5000} className={`${input} mt-1`} rows={2} value={fields.terms} onChange={(event) => setFields({ ...fields, terms: event.target.value })}/></label><div className="flex flex-wrap gap-2"><button disabled={busy} className="rounded-xl bg-[#681B1D] px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">Save draft</button><button disabled={busy} type="button" onClick={() => void save(true)} className="rounded-xl border border-[#681B1D] px-4 py-2 text-sm font-semibold text-[#681B1D] disabled:opacity-50">Save and submit for review</button></div></form>}
    {loading ? <p role="status" className="py-8 text-center text-sm text-[#7D6B63]">Loading listings…</p> : filtered.length ? <div className="grid gap-3 lg:grid-cols-2">{filtered.map((item) => <article key={item.id} className="rounded-2xl border border-[#EAD2B0] p-4 dark:border-[#4D3331]"><div className="flex items-start justify-between gap-3"><div><span className="text-[10px] font-bold uppercase tracking-wider text-[#B77A36]">{item.category}{item.subcategory ? ` · ${item.subcategory}` : ""}</span><h3 className="mt-1 font-serif text-lg font-bold">{item.name}</h3><p className="mt-1 text-xs text-[#7D6B63]">{item.description || "No description added."}</p></div><span className="rounded-full bg-[#EAD2B0]/50 px-2.5 py-1 text-[10px] font-semibold capitalize">{item.status.replaceAll("_", " ")}</span></div>{item.starting_price !== null && <p className="mt-3 text-sm font-semibold">{item.pricing_model === "starting_at" ? "From " : ""}₹{(item.starting_price / 100).toLocaleString("en-IN")}</p>}{item.moderation_note && <p className="mt-2 rounded-lg bg-rose-50 p-2 text-xs text-rose-800">Review note: {item.moderation_note}</p>}<div className="mt-4 flex flex-wrap gap-3 text-xs font-semibold text-[#681B1D]">{["draft", "rejected"].includes(item.status) && <><button onClick={() => edit(item)} className="underline">Edit</button><button disabled={busy} onClick={() => void action(item.id, "submit")} className="underline">Submit for review</button><button disabled={busy} onClick={() => void action(item.id, "delete")} className="text-rose-700 underline">Delete</button></>}{item.status === "published" && <a href={`/vendors/${item.vendor_profile_id}`} className="underline">Preview storefront</a>}<button onClick={() => setAddonsOpenId(addonsOpenId === item.id ? null : item.id)} className="underline">{addonsOpenId === item.id ? "Close add-ons" : "Manage add-ons"}</button></div>{addonsOpenId === item.id && <VendorListingAddonsManager listingId={item.id} onChanged={() => void refresh()}/>}</article>)}</div> : <div className="rounded-2xl bg-[#FFF3E3] p-8 text-center text-sm text-[#7D6B63] dark:bg-[#1A1211]">No listings in this section yet. Create a draft to start your catalog.</div>}
  </section>;
}
